type Attributes = Record<string, unknown>;
type Renames = Record<string, string>;
/**
 * The selected list columns live in the browser. A renamed field is no longer
 * on the schema, so replace it with the name from the server map and drop a
 * name that was deleted. A name that still exists is left alone, even when an
 * older map mentions it.
 */
declare const applyAttributeRenamesToHeaders: (headers: string[], attributes: Attributes, renames: Renames) => string[];
declare const applyAttributeRenamesToSort: (sort: string, attributes: Attributes, renames: Renames) => string;
declare const applyAttributeRenamesToFilters: <T>(filters: T, attributes: Attributes, renames: Renames, renameKeys?: boolean) => T;
export { applyAttributeRenamesToFilters, applyAttributeRenamesToHeaders, applyAttributeRenamesToSort, };
